cssCode:
.skeleton-card {
  width: 250px;
  height: 100px;
  border-radius: 15px;
  background: #1e1e1e;
  display: flex;
  align-items: center;
  padding: 15px;
  box-sizing: border-box;
  gap: 15px;
}
.skeleton-avatar {
  width: 50px; height: 50px;
  border-radius: 50%;
}
.skeleton-text-wrap {
  display: flex; flex-direction: column; gap: 10px; flex: 1;
}
.skeleton-text {
  height: 10px; border-radius: 5px;
}
.skeleton-text.short { width: 60%; }
.skeleton-text.long { width: 100%; }

.shimmer {
  background: linear-gradient(90deg, #2a2a2a 25%, #3f3f3f 50%, #2a2a2a 75%);
  background-size: 200% 100%;
  animation: shimmerAnim 1.5s infinite linear;
}
@keyframes shimmerAnim {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const card = document.createElement('div');
card.className = 'skeleton-card';

const avatar = document.createElement('div');
avatar.className = 'skeleton-avatar shimmer';

const textWrap = document.createElement('div');
textWrap.className = 'skeleton-text-wrap';

const text1 = document.createElement('div');
text1.className = 'skeleton-text long shimmer';
const text2 = document.createElement('div');
text2.className = 'skeleton-text short shimmer';

textWrap.appendChild(text1);
textWrap.appendChild(text2);
card.appendChild(avatar);
card.appendChild(textWrap);
c.appendChild(card);
